// A37: септаккорды от тоники r на E: m7, доминантсептаккорд, maj7
function a37(r){
  const m7=x=>`E${x} A${x-2} A${x+2} D${x}`,d7=x=>`E${x} A${x-1} A${x+2} D${x}`,mj7=x=>`E${x} A${x-1} A${x+2} D${x+1}`;
  const up=`E${r} A${r-2} A${r+2} D${r} D${r+2} G${r}`,dn=up.split(' ').reverse().join(' ');
  const u2=(x,t,s)=>`E${x} A${x-1+t} A${x+2} D${x+s} D${x+2} G${x+1-t}`,d2=(x,t,s)=>u2(x,t,s).split(' ').reverse().join(' ');
  return [R(m7(r),4),J(R(m7(r),2),R(d7(r),2)),J(m7(r),mj7(r+1),d7(r+3),m7(r)),{sub:6,t:J(up,dn,up,dn)},{sub:6,t:J(up,d2(r+1,0,1),u2(r+3,0,0),dn)}];
}
// L38: хроматический проход к тонике x и обратно к r на струне E; на 3–4 уровне — к ноте на A
function l38(r,x){
  return [J(R(`E${r}`,12),`E${x-4} E${x-3} E${x-2} E${x-1}`,R(`E${x}`,12),`E${r-4} E${r-3} E${r-2} E${r-1}`),J(R(`E${r}`,12),`E${x+4} E${x+3} E${x+2} E${x+1}`,R(`E${x}`,12),`E${r+4} E${r+3} E${r+2} E${r+1}`),J(R(`E${r}`,12),`E${r+1} E${r+2} E${r+3} E${r+4}`,R(`A${r}`,12),`A${r-1} E${r+3} E${r+2} E${r+1}`),J(`E${r} E${r} . E${r}`,`Ex E${r} E${r} .`,`E${r+1} E${r+2} E${r+3} E${r+4}`,R(`A${r}`,4),`A${r} . Ax A${r}`,`A${r} A${r} . .`,`A${r-1} E${r+3} E${r+2} E${r+1}`,`E${r} . . .`),J(`E${r} Ex E${r} E${r}`,`E${r+1} E${r+2} E${r+3} E${r+4}`,`A${r} Ax A${r} A${r}`,`A${r+1} A${r+2} A${r+3} A${r+4}`,`D${r} Dx D${r} D${r}`,`D${r-1} A${r+3} A${r+2} A${r+1}`,`A${r} Ax A${r} A${r}`,`A${r-1} E${r+3} E${r+2} E${r+1}`)];
}
