const GROUPS_BASS={R:['R6','R7','R8','R9','R10','R11','R12','R13','R14','R15'],A:['A16','A17','A18','A19','A20','A21','A22','A23','A37'],L:['L24','L25','L26','L27','L28','L29','L30','L31','L38'],C:['C32','C33','C34','C35','C36']};
